@mcp.tool()
def get_tum_config() -> str:
    """Get TUM (Token Usage Manager) service configuration.

    Returns the base URL and whether an admin token is set.
    Use this to find the TUM endpoint before making API key requests.
    """
    from core import paths as _p
    import yaml as _yaml

    tum_path = _p.config_dir() / "tum_status.yaml"
    base_url = os.environ.get("TUM_BASE_URL", "http://localhost:8001")
    admin_token_set = False
    if tum_path.exists():
        data = _yaml.safe_load(tum_path.read_text()) or {}
        url = data.get("base_url", "").strip()
        if url:
            base_url = url
        admin_token_set = bool(data.get("admin_token"))
    return json.dumps({
        "base_url": base_url,
        "admin_token_set": admin_token_set,
    }, ensure_ascii=False)


@mcp.tool()
def feishu_send_result_card(
    exp_id: str,
    conclusion: str,
    key_metrics: dict[str, Any] | None = None,
    baseline_comparison: str = "",
) -> str:
    """Send a formatted result card when an experiment completes.
    Always sent to the user-facing group (Group A).

    Args:
        exp_id: Experiment identifier.
        conclusion: Conclusion: success/negative/failed/killed.
        key_metrics: Dict of metric_name → value.
        baseline_comparison: Baseline comparison text.
    """
    chat_id = _resolve_user_group_chat()
    result = feishu.send_result_card(exp_id, conclusion, key_metrics, baseline_comparison, chat_id)
    return _tool_result_to_str(result)


@mcp.tool()
def feishu_read_pending_inputs(
    page_size: int = 50,
) -> str:
    """Read new messages from Feishu chat since last sync point.

    Args:
        page_size: Max messages per page.
    """
    chat_id = _get_session_chat_id()
    result = feishu.read_pending_inputs(chat_id, page_size)
    return _tool_result_to_str(result)
